import { bn } from '@/shared/lib/bn';
import { tr } from '@/shared/lib/i18n';
import { pick, Q, wrongs } from './q';
import type { Generator, LevelBank } from './types';

/* Our own questions for chapter 4 (levels 16–21). First option is always right. */
const n = (v: number) => bn(v);
const d = (v: number) => (v >= 1000 ? bn(v) : bn(Math.round(v * 10) / 10, { grouping: false }));
const mil = (m: number) => (m >= 10 ? `${n(m / 10)} কোটি` : `${n(m * 10)} লাখ`);

const indexMem: Generator = {
  id: 'l16-g1', concept: 'memory',
  make: (rand) => {
    const m = pick(rand, [50, 100, 200, 500]), b = pick(rand, [8, 16, 24]);
    const gb = (m * b) / 1000;
    const opts = wrongs(gb, [gb * 1000, gb / 10, gb * 8]);
    return {
      prompt: tr(`${mil(m)} দোকান, index-এ প্রতিটার জন্য ${n(b)} byte। মোট memory কত?`, `${n(m)} million businesses, ${n(b)} bytes each in the index. Total memory?`),
      options: [`~${d(gb)} GB`, ...opts.map((o) => `~${d(o)} GB`)],
      explain: tr(`${mil(m)} × ${n(b)} byte ≈ ${d(gb)} GB: এক server-এর memory-তে আঁটে।`, `${n(m)}M × ${n(b)} B ≈ ${d(gb)} GB, which fits in one server's memory.`),
    };
  },
};
const pubsubServers: Generator = {
  id: 'l17-g1', concept: 'servers',
  make: (rand) => {
    const u = pick(rand, [10, 50, 100]), every = pick(rand, [15, 30, 60]), cap = 100_000;
    const right = Math.ceil((u * 1e6) / every / cap);
    return {
      prompt: tr(`${mil(u)} সক্রিয় user, প্রত্যেকে ${n(every)} সেকেন্ডে একবার অবস্থান পাঠায়। এক server সেকেন্ডে ১ লাখ update সামলায়। কয়টা server?`, `${n(u)} million active users each send their location every ${n(every)} s. One server handles 100,000 updates a second. How many servers?`),
      options: [n(right), ...wrongs(right, [Math.ceil((u * 1e6) / cap), right * 2, Math.ceil(right / 2), right + 5]).map(n)],
      explain: tr(`${mil(u)} ÷ ${n(every)} ≈ সেকেন্ডে ${n(Math.round((u * 1e6) / every))} update; ÷ ১ লাখ = ${n(right)}।`, `${n(u)}M ÷ ${n(every)} ≈ ${n(Math.round((u * 1e6) / every))} updates a second; ÷ 100,000 = ${n(right)}.`),
    };
  },
};
const tileCount: Generator = {
  id: 'l18-g1', concept: 'tiles',
  make: (rand) => {
    const z = pick(rand, [2, 3, 4, 5, 6]);
    const right = 4 ** z;
    return {
      prompt: tr(`প্রতি zoom ধাপে প্রতিটা tile চার ভাগ হয়। Zoom ${n(z)}-এ পৃথিবী কয়টা tile?`, `Each zoom step splits every tile into four. How many tiles cover the world at zoom ${n(z)}?`),
      options: [n(right), ...wrongs(right, [2 ** z, 4 ** (z - 1), 4 ** (z + 1), z * 4]).map(n)],
      explain: tr(`৪^${n(z)} = ${n(right)}; ধাপে ধাপে চারগুণ।`, `4^${n(z)} = ${n(right)}; four times more at every step.`),
    };
  },
};
const retentionDisk: Generator = {
  id: 'l19-g1', concept: 'retention',
  make: (rand) => {
    const mb = pick(rand, [10, 50, 100]), days = pick(rand, [1, 3, 7]);
    const tb = Math.round(((mb * 86400 * days) / 1e6) * 10) / 10;
    const opts = wrongs(tb, [Math.round(tb * 1000), Math.round((tb / 24) * 10) / 10, Math.round(tb * 7 * 10) / 10]);
    return {
      prompt: tr(`সেকেন্ডে ${n(mb)} MB message আসে, রাখতে হবে ${n(days)} দিন। এক কপির জন্য কত disk?`, `${n(mb)} MB of messages arrive a second and are kept ${n(days)} day${days > 1 ? 's' : ''}. Disk for one copy?`),
      options: [`~${d(tb)} TB`, ...opts.map((o) => `~${d(o)} TB`)],
      explain: tr(`${n(mb)} MB × ৮৬,৪০০ × ${n(days)} ≈ ${d(tb)} TB; replica থাকলে তার গুণ।`, `${n(mb)} MB × 86,400 × ${n(days)} ≈ ${d(tb)} TB; multiply by the replica count.`),
    };
  },
};
const scrapeRate: Generator = {
  id: 'l20-g1', concept: 'writes',
  make: (rand) => {
    const hosts = pick(rand, [1000, 5000, 20000]), per = pick(rand, [100, 500]), every = pick(rand, [10, 15, 30]);
    const right = Math.round((hosts * per) / every);
    return {
      prompt: tr(`${n(hosts)} server, প্রতিটায় ${n(per)}টা metric, প্রতি ${n(every)} সেকেন্ডে সংগ্রহ। সেকেন্ডে কয়টা data point লেখা হয়?`, `${n(hosts)} servers, ${n(per)} metrics each, collected every ${n(every)} s. Data points written a second?`),
      options: [n(right), ...wrongs(right, [hosts * per, Math.round((hosts * per) / 60), Math.round(right / 10)]).map(n)],
      explain: tr(`${n(hosts)} × ${n(per)} ÷ ${n(every)} = ${n(right)}; পড়ার চেয়ে লেখা অনেক বেশি।`, `${n(hosts)} × ${n(per)} ÷ ${n(every)} = ${n(right)}; writes far outnumber reads.`),
    };
  },
};
const hotNodes: Generator = {
  id: 'l21-g1', concept: 'hotspot',
  make: (rand) => {
    const total = pick(rand, [50_000, 100_000, 200_000]), share = pick(rand, [20, 30, 40]), cap = pick(rand, [5000, 10_000]);
    const right = Math.ceil(((share / 100) * total) / cap);
    return {
      prompt: tr(`সেকেন্ডে ${n(total)}টা scan, এর ${n(share)}% এক hub-এর। এক node সেকেন্ডে ${n(cap)}টা গোনে। ওই hub-এর জন্য কয়টা node?`, `${n(total)} scans a second, ${n(share)}% of them from one hub. A node counts ${n(cap)} a second. Nodes for that hub?`),
      options: [n(right), ...wrongs(right, [Math.ceil(total / cap), 1, right * 2, right + 3]).map(n)],
      explain: tr(`${n(share)}% × ${n(total)} = ${n((share / 100) * total)}; ÷ ${n(cap)} = ${n(right)}। পরে ভাগগুলো যোগ করুন।`, `${n(share)}% × ${n(total)} = ${n((share / 100) * total)}; ÷ ${n(cap)} = ${n(right)}. Sum the partial counts afterwards.`),
    };
  },
};

